CREATE TABLE evidence(id TEXT PRIMARY KEY, source TEXT, position INTEGER,
 event TEXT, stamp TEXT, epoch_ns INTEGER, raw TEXT, cycle TEXT, suppressed INTEGER DEFAULT 0);
INSERT INTO "evidence" VALUES('log:1:2:0:0','1:2:0',0,'startup','2026-10-11 12:00:00 +0800',1791691200000000000,'apcupsd 3.14.14 (31 May 2016) debian startup succeeded',NULL,0);
